-- superspar-renbro-hammanskraal (owner)
UPDATE businesses SET description = 'SUPERSPAR Renbro is a full-service supermarket at Shop 12, Renbro Shopping Centre, Old Warmbaths Road, Hammanskraal, offering fresh produce, an in-store bakery, butchery and deli alongside everyday groceries, pantry staples and household essentials. As a SUPERSPAR, a larger-format supermarket with a selling area typically of at least 1,300 square metres, it is built for a complete weekly shop rather than only convenience purchases. The store primarily serves the Hammanskraal community and surrounding residential areas, handling regular household grocery shopping and larger fresh-food purchases, and offers in-store shopping alongside pickup and delivery. It is part of the Renbro retail centre, where the same local retail group also runs Renbro TOPS. It trades from 7am to 7pm Monday to Saturday, and from 7am to 4pm on Sundays.', description_enriched_at = datetime('now') WHERE slug = 'superspar-renbro-hammanskraal' AND description = 'SuperSpar Renbro is a supermarket at Renbro Shopping Centre in Hammanskraal.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
